317	    style: TextStyleDeclaration,
318	    useWhiteSpace?: boolean,
319	  ) {
320	    const {
321	      fontFamily,
322	      strokeWidth,
323	      stroke,
324	      fill,
325	      fontSize,
326	      fontStyle,
327	      fontWeight,
328	      deltaY,
329	      textDecorationThickness,
330	      linethrough,
331	      overline,
