346	            !fontFamily.includes("'") && !fontFamily.includes('"')
347	              ? `'${fontFamily}'`
348	              : fontFamily
349	          }; `
350	        : '',
351	      fontSize ? `font-size: ${fontSize}px; ` : '',
352	      fontStyle ? `font-style: ${fontStyle}; ` : '',
353	      fontWeight ? `font-weight: ${fontWeight}; ` : '',
354	      textDecoration
355	        ? `text-decoration: ${textDecoration}; text-decoration-thickness: ${toFixed((thickness * this.getObjectScaling().y) / 10, config.NUM_FRACTION_DIGITS)}%; `
356	        : '',
357	      fill ? colorPropToSVG(FILL, fill) : '',
358	      deltaY ? `baseline-shift: ${-deltaY}; ` : '',
