368	  getSvgTextDecoration(
369	    this: TextSVGExportMixin & FabricText,
370	    style: TextStyleDeclaration,
371	  ) {
372	    return (['overline', 'underline', 'line-through'] as const)
373	      .filter(
374	        (decoration) =>
375	          style[
376	            decoration.replace('-', '') as
377	              | 'overline'
378	              | 'underline'
379	              | 'linethrough'
380	          ],
381	      )
382	      .join(' ');
383	  }
