      canvas.setZoom(20);
      const clip = new fabric.Circle({
        radius: 5,
        strokeWidth: 0,
        top: 3,
        left: 3,
      });

      const rect = new fabric.Rect({
        top: 5,
        left: 5,
        strokeWidth: 0,
        width: 10,
        height: 10,
        fill: 'rgba(255,0,0,0.5)',
      });

      rect.clipPath = clip;
      canvas.add(rect);
    },
  },
  {
    title: 'Clip a group with a circle',
    golden: 'clipping2_SVG.png',
    percentage: 0.06,
    size: [200, 200],
    async renderFunction(canvas, fabric) {
      const clipPath = new fabric.Circle({
        radius: 100,
        top: 0,
        left: 0,
      });

      const group = new fabric.Group(
        [
          new fabric.Rect({
            strokeWidth: 0,
            width: 100,
            height: 100,
            top: 50,
            left: 50,
            fill: 'red',
