import { describe, it } from 'vitest';
import { FabricText } from '../shapes/Text/Text';
import { config } from '../config';

describe('repro', () => {
  it('multiline deltaY', () => {
    config.configure({ NUM_FRACTION_DIGITS: 2 });
    const text = new FabricText('ab\ncd', {
      left: 0, top: 0,
      styles: { 1: { 1: { deltaY: -10, fontSize: 20 } } },
    });
    console.log(text.toSVG());
  });
});
EOF
npx vitest run --project unit-node src/__repro__/repro.spec.ts 2>&1 | grep -A6 "tspan\|<g "

cat > /app/src/__repro__/repro.spec.ts << 'EOF'
import { describe, it } from 'vitest';
import { FabricText } from '../shapes/Text/Text';
import { config } from '../config';

describe('repro', () => {
  it('offset chars', () => {
    config.configure({ NUM_FRACTION_DIGITS: 2 });
    const text = new FabricText('Hello world', {
      left: 0, top: 0,
      styles: { 0: { 7: { deltaY: -12, fontSize: 24 }, 8: { deltaY: 8, fontSize: 24 } } },
    });
    console.log('OFFSET:', text.toSVG().match(/<tspan.*<\/tspan>/)?.[0]);
  });
  it('scaled underline thickness', () => {
    config.configure({ NUM_FRACTION_DIGITS: 2 });
    const t1 = new FabricText('ab', { underline: true, scaleX: 3, scaleY: 3 });
    const t2 = new FabricText('ab', { underline: true });
    console.log('scaled x3:', t1.toSVG().match(/text-decoration-thickness: [^;]+;/g));
    console.log('unscaled:', t2.toSVG().match(/text-decoration-thickness: [^;]+;/g));
  });
  it('char-level thickness scaled', () => {
    config.configure({ NUM_FRACTION_DIGITS: 2 });
    const t = new FabricText('ab', { scaleX: 4, scaleY: 4, styles: { 0: { 0: { underline: true, textDecorationThickness: 120 } } } });
    console.log('char-level scaled x4:', t.toSVG().match(/text-decoration-thickness: [^;]+;/g));
  });
});
EOF
npx vitest run --project unit-node src/__repro__/repro.spec.ts 2>&1 | grep -E "OFFSET:|scaled|unscaled|char-level"

